-- ===== 20261011000200_functions.sql =====
-- Re·Form Pilates — booking engine
-- Every capacity-changing operation locks the class_sessions row (SELECT ... FOR UPDATE),
-- so concurrent requests for the last reformer are serialised and only one can win.
-- These functions are SECURITY DEFINER and executable only by service_role: the
-- Next.js server verifies the user's session and passes the profile id explicitly.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.settings() returns public.studio_settings
language sql stable security definer set search_path = public as $$
  select * from public.studio_settings where id = 1
$$;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where user_id = auth.uid() and role = 'admin' and deleted_at is null)
$$;

create or replace function public.my_profile_id() returns uuid
language sql stable security definer set search_path = public as $$
  select id from public.profiles where user_id = auth.uid() and deleted_at is null
$$;

-- Spots in use: confirmed + live holds + live waitlist offers (an offer reserves the spot).
create or replace function public.spots_taken(p_session uuid, p_exclude_profile uuid default null) returns int
language sql stable security definer set search_path = public as $$
  select
    (select count(*) from public.bookings b
      where b.session_id = p_session
        and (b.status = 'confirmed' or (b.status = 'held' and b.hold_expires_at > now()))
        and (p_exclude_profile is null or b.profile_id <> p_exclude_profile))::int
  + (select count(*) from public.waitlist_entries w
      where w.session_id = p_session and w.status = 'offered' and w.offer_expires_at > now()
        and (p_exclude_profile is null or w.profile_id <> p_exclude_profile))::int
$$;

-- Give a credit back: to its original lot if still valid, otherwise a fresh 30-day lot.
create or replace function public.return_credit(p_booking uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare
  b public.bookings;
  lot public.credit_lots;
  kind public.credit_kind;
  new_lot uuid;
begin
  select * into b from public.bookings where id = p_booking;
  select ct.credit_kind into kind
    from public.class_sessions s join public.class_types ct on ct.id = s.class_type_id
   where s.id = b.session_id;

  if b.paid_with = 'credit' and b.credit_lot_id is not null then
    select * into lot from public.credit_lots where id = b.credit_lot_id for update;
    if lot.expires_at is null or lot.expires_at > now() + interval '1 day' then
      update public.credit_lots set remaining = remaining + 1 where id = lot.id;
      insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, reason, booking_id)
        values (b.profile_id, lot.id, lot.credit_kind, 1, p_reason, b.id);
      return;
    end if;
    kind := lot.credit_kind;
  elsif b.paid_with = 'payment' then
    if kind is null then
      -- Events have no credit type: flag the payment for a manual refund.
      update public.payments set status = 'needs_refund' where id = b.payment_id and status = 'paid';
      return;
    end if;
  else
    return; -- manual / free bookings: nothing to give back
  end if;

  insert into public.credit_lots (profile_id, credit_kind, total, remaining, expires_at, note)
    values (b.profile_id, kind, 1, 1, now() + interval '30 days', 'Returned: ' || p_reason)
    returning id into new_lot;
  insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, reason, booking_id)
    values (b.profile_id, new_lot, kind, 1, p_reason, b.id);
end $$;

-- When a spot is re-filled, refund the oldest late cancellation flagged for it.
create or replace function public.apply_late_fill_refund(p_session uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  late_id uuid;
begin
  select id into late_id from public.bookings
   where session_id = p_session and status = 'late_cancelled' and late_refund_pending
   order by cancelled_at limit 1 for update;
  if late_id is null then return null; end if;
  update public.bookings set late_refund_pending = false where id = late_id;
  perform public.return_credit(late_id, 'late_fill_refund');
  return late_id;
end $$;

-- ---------------------------------------------------------------------------
-- Booking
-- p_mode: 'credit' (confirm now), 'payment' (hold while paying), 'manual' / 'free' (admin)
-- ---------------------------------------------------------------------------
create or replace function public.book_session(
  p_profile uuid, p_session uuid, p_mode text, p_source public.booking_source default 'online'
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.class_sessions;
  ct public.class_types;
  cfg public.studio_settings := public.settings();
  lot public.credit_lots;
  new_id uuid;
  st public.booking_status;
begin
  select * into s from public.class_sessions where id = p_session for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if s.status <> 'scheduled' then raise exception 'class_cancelled' using errcode = 'P0001'; end if;
  if p_source = 'online' and s.starts_at <= now() then raise exception 'class_started' using errcode = 'P0001'; end if;
  if p_source = 'manual' and s.ends_at <= now() - interval '1 day' then raise exception 'class_past' using errcode = 'P0001'; end if;

  select * into ct from public.class_types where id = s.class_type_id;

  -- Clear stale holds for this class so they don't block the unique index or capacity.
  update public.bookings set status = 'expired'
   where session_id = p_session and status = 'held' and hold_expires_at <= now();

  if exists (select 1 from public.bookings where session_id = p_session and profile_id = p_profile and status in ('held','confirmed')) then
    raise exception 'already_booked' using errcode = 'P0001';
  end if;

  if public.spots_taken(p_session, p_profile) >= s.capacity then
    raise exception 'full' using errcode = 'P0001';
  end if;

  if p_mode = 'credit' then
    if ct.credit_kind is null then raise exception 'credits_not_accepted' using errcode = 'P0001'; end if;
    select * into lot from public.credit_lots
     where profile_id = p_profile and credit_kind = ct.credit_kind and remaining > 0
       and (expires_at is null or expires_at > s.starts_at)
     order by expires_at nulls last, created_at
     limit 1 for update;
    if not found then raise exception 'no_credits' using errcode = 'P0001'; end if;
    update public.credit_lots set remaining = remaining - 1 where id = lot.id;
    insert into public.bookings (session_id, profile_id, status, source, paid_with, credit_lot_id, confirmed_at)
      values (p_session, p_profile, 'confirmed', p_source, 'credit', lot.id, now())
      returning id into new_id;
    insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, reason, booking_id)
      values (p_profile, lot.id, lot.credit_kind, -1, 'booking', new_id);
    st := 'confirmed';
  elsif p_mode = 'payment' then
    insert into public.bookings (session_id, profile_id, status, source, hold_expires_at)
      values (p_session, p_profile, 'held', p_source, now() + make_interval(mins => cfg.hold_minutes))
      returning id into new_id;
    st := 'held';
  elsif p_mode in ('manual', 'free') then
    insert into public.bookings (session_id, profile_id, status, source, paid_with, confirmed_at)
      values (p_session, p_profile, 'confirmed', p_source, p_mode::public.paid_with, now())
      returning id into new_id;
    st := 'confirmed';
  else
    raise exception 'bad_mode' using errcode = 'P0001';
  end if;

  -- A waitlist offer or entry for this client is now fulfilled.
  update public.waitlist_entries set status = 'claimed'
   where session_id = p_session and profile_id = p_profile and status in ('waiting', 'offered');

  if st = 'confirmed' then perform public.apply_late_fill_refund(p_session); end if;

  return jsonb_build_object('booking_id', new_id, 'status', st);
end $$;

-- Called by the payment webhook (or mock checkout) once money has actually moved.
create or replace function public.confirm_payment(p_payment uuid, p_provider_ref text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  p public.payments;
  b public.bookings;
  s public.class_sessions;
  prod public.products;
  lot_id uuid;
begin
  select * into p from public.payments where id = p_payment for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p.status = 'paid' then return jsonb_build_object('status', 'already_paid', 'booking_id', p.booking_id); end if;

  update public.payments set status = 'paid', paid_at = now(), provider_ref = coalesce(p_provider_ref, provider_ref)
   where id = p.id;

  if p.purpose = 'pack' then
    select * into prod from public.products where id = p.product_id;
    insert into public.credit_lots (profile_id, credit_kind, total, remaining, expires_at, payment_id, note)
      values (p.profile_id, prod.credit_kind, prod.credits, prod.credits,
              case when prod.validity_days is null then null else now() + make_interval(days => prod.validity_days) end,
              p.id, prod.name)
      returning id into lot_id;
    insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, reason)
      values (p.profile_id, lot_id, prod.credit_kind, prod.credits, 'purchase');
    return jsonb_build_object('status', 'credits_added', 'lot_id', lot_id);
  end if;

  select * into b from public.bookings where id = p.booking_id for update;
  select * into s from public.class_sessions where id = b.session_id for update;

  if b.status = 'confirmed' then
    return jsonb_build_object('status', 'confirmed', 'booking_id', b.id);
  end if;

  -- Hold still valid, or expired but the spot is still free: confirm.
  if s.status = 'scheduled' and (
       (b.status = 'held' and b.hold_expires_at > now())
       or public.spots_taken(s.id, b.profile_id) < s.capacity
     ) and not exists (
       select 1 from public.bookings x where x.session_id = s.id and x.profile_id = b.profile_id
        and x.status = 'confirmed' and x.id <> b.id)
  then
    update public.bookings set status = 'confirmed', paid_with = 'payment', payment_id = p.id,
           hold_expires_at = null, confirmed_at = now()
     where id = b.id;
    perform public.apply_late_fill_refund(s.id);
    return jsonb_build_object('status', 'confirmed', 'booking_id', b.id);
  end if;

  -- Paid too late and the spot is gone: flag for refund.
  update public.bookings set status = 'expired', payment_id = p.id where id = b.id;
  update public.payments set status = 'needs_refund' where id = p.id;
  return jsonb_build_object('status', 'needs_refund', 'booking_id', b.id);
end $$;

-- ---------------------------------------------------------------------------
-- Waitlist
-- ---------------------------------------------------------------------------
create or replace function public.join_waitlist(p_profile uuid, p_session uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.class_sessions;
  new_id uuid;
  pos int;
begin
  select * into s from public.class_sessions where id = p_session for update;
  if not found or s.status <> 'scheduled' then raise exception 'class_cancelled' using errcode = 'P0001'; end if;
  if s.starts_at <= now() then raise exception 'class_started' using errcode = 'P0001'; end if;
  if exists (select 1 from public.bookings where session_id = p_session and profile_id = p_profile and status in ('held','confirmed')) then
    raise exception 'already_booked' using errcode = 'P0001';
  end if;
  if public.spots_taken(p_session) < s.capacity then raise exception 'not_full' using errcode = 'P0001'; end if;

  insert into public.waitlist_entries (session_id, profile_id) values (p_session, p_profile)
    on conflict do nothing returning id into new_id;
  if new_id is null then raise exception 'already_waitlisted' using errcode = 'P0001'; end if;

  select count(*) into pos from public.waitlist_entries
   where session_id = p_session and status = 'waiting'
     and created_at <= (select created_at from public.waitlist_entries where id = new_id);
  return jsonb_build_object('entry_id', new_id, 'position', pos);
end $$;

-- Expire stale offers and offer free spots to the next people in line.
-- Returns the entries that just received an offer (the app notifies them).
create or replace function public.process_waitlist(p_session uuid)
returns table (entry_id uuid, profile_id uuid, offer_expires_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare
  s public.class_sessions;
  cfg public.studio_settings := public.settings();
  free int;
  nxt public.waitlist_entries;
  exp timestamptz;
begin
  select * into s from public.class_sessions where id = p_session for update;
  if not found then return; end if;

  update public.waitlist_entries w set status = 'expired'
   where w.session_id = p_session and w.status = 'offered' and w.offer_expires_at <= now();
  update public.bookings set status = 'expired'
   where session_id = p_session and status = 'held' and hold_expires_at <= now();

  if s.status <> 'scheduled' or s.starts_at <= now() then return; end if;

  free := s.capacity - public.spots_taken(p_session);
  while free > 0 loop
    select * into nxt from public.waitlist_entries w
     where w.session_id = p_session and w.status = 'waiting'
     order by w.created_at limit 1 for update;
    exit when not found;

    -- Offer window: N minutes, but not past the cancellation cutoff;
    -- if we're already inside the cutoff, until the class starts.
    exp := least(now() + make_interval(mins => cfg.waitlist_window_minutes),
                 s.starts_at - make_interval(hours => cfg.cancellation_cutoff_hours));
    if exp <= now() + interval '10 minutes' then
      exp := least(now() + make_interval(mins => cfg.waitlist_window_minutes), s.starts_at);
    end if;

    update public.waitlist_entries set status = 'offered', offered_at = now(), offer_expires_at = exp
     where id = nxt.id;
    entry_id := nxt.id; profile_id := nxt.profile_id; offer_expires_at := exp;
    return next;
    free := free - 1;
  end loop;
end $$;

create or replace function public.leave_waitlist(p_profile uuid, p_entry uuid)
returns table (entry_id uuid, profile_id uuid, offer_expires_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare
  w public.waitlist_entries;
begin
  select * into w from public.waitlist_entries where id = p_entry and waitlist_entries.profile_id = p_profile for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  update public.waitlist_entries set status = 'left' where id = w.id and status in ('waiting', 'offered');
  return query select * from public.process_waitlist(w.session_id);
end $$;

-- ---------------------------------------------------------------------------
-- Cancellation
-- ---------------------------------------------------------------------------
create or replace function public.cancel_booking(p_booking uuid, p_profile uuid, p_admin boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  b public.bookings;
  s public.class_sessions;
  cfg public.studio_settings := public.settings();
  late boolean;
  result text;
begin
  select * into b from public.bookings where id = p_booking;
  if not found or (not p_admin and b.profile_id <> p_profile) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select * into s from public.class_sessions where id = b.session_id for update;
  select * into b from public.bookings where id = p_booking for update;

  if b.status = 'held' then
    update public.bookings set status = 'expired', cancelled_at = now() where id = b.id;
    return jsonb_build_object('status', 'released', 'session_id', s.id);
  end if;
  if b.status <> 'confirmed' then raise exception 'not_cancellable' using errcode = 'P0001'; end if;
  if s.starts_at <= now() and not p_admin then raise exception 'class_started' using errcode = 'P0001'; end if;

  late := now() > s.starts_at - make_interval(hours => cfg.cancellation_cutoff_hours);

  if late and not p_admin then
    update public.bookings set status = 'late_cancelled', cancelled_at = now(),
           late_refund_pending = cfg.refund_late_cancel_if_filled and paid_with in ('credit', 'payment')
     where id = b.id;
    result := 'late_cancelled';
  else
    update public.bookings set status = 'cancelled', cancelled_at = now() where id = b.id;
    perform public.return_credit(b.id, 'cancel_refund');
    result := 'cancelled';
  end if;

  return jsonb_build_object('status', result, 'session_id', s.id);
end $$;

-- Studio cancels a class: every booking is cancelled and refunded (credit back,
-- or a credit for card payments; events are flagged for a manual refund).
create or replace function public.cancel_session(p_session uuid, p_reason text)
returns table (booking_id uuid, profile_id uuid)
language plpgsql security definer set search_path = public as $$
declare
  s public.class_sessions;
  r record;
begin
  select * into s from public.class_sessions where id = p_session for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if s.status = 'cancelled' then return; end if;

  update public.class_sessions set status = 'cancelled', cancelled_reason = p_reason where id = p_session;

  for r in select b.id, b.profile_id, b.status from public.bookings b
            where b.session_id = p_session and b.status in ('confirmed', 'held') for update
  loop
    update public.bookings set status = 'studio_cancelled', cancelled_at = now() where id = r.id;
    if r.status = 'confirmed' then
      perform public.return_credit(r.id, 'studio_cancel');
      booking_id := r.id; profile_id := r.profile_id;
      return next;
    end if;
  end loop;

  update public.waitlist_entries set status = 'cancelled'
   where session_id = p_session and status in ('waiting', 'offered');
end $$;

-- ---------------------------------------------------------------------------
-- Periodic tick: expire holds and offers, advance waitlists.
-- ---------------------------------------------------------------------------
create or replace function public.tick()
returns table (entry_id uuid, profile_id uuid, offer_expires_at timestamptz)
language plpgsql security definer set search_path = public as $$
declare
  sid uuid;
begin
  for sid in
    select distinct w.session_id from public.waitlist_entries w
      join public.class_sessions s on s.id = w.session_id
     where s.status = 'scheduled' and s.starts_at > now()
       and (w.status = 'waiting' or (w.status = 'offered' and w.offer_expires_at <= now()))
  loop
    return query select * from public.process_waitlist(sid);
  end loop;
  update public.bookings set status = 'expired' where status = 'held' and hold_expires_at <= now();
  update public.waitlist_entries w set status = 'expired'
   where w.status in ('waiting', 'offered')
     and exists (select 1 from public.class_sessions s where s.id = w.session_id and s.starts_at <= now());
end $$;

-- ---------------------------------------------------------------------------
-- Timetable → sessions
-- ---------------------------------------------------------------------------
create or replace function public.generate_sessions(p_template uuid) returns int
language plpgsql security definer set search_path = public as $$
declare
  t public.timetable_templates;
  tz text := (public.settings()).timezone;
  n int;
begin
  select * into t from public.timetable_templates where id = p_template;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;

  with days as (
    select d::date as day from generate_series(t.valid_from, t.valid_to, interval '1 day') d
  ), rows as (
    select ts.class_type_id,
           ((dy.day + ts.start_time) at time zone tz) as starts_at,
           coalesce(ts.duration_minutes, ct.default_duration_minutes) as dur,
           coalesce(ts.capacity, ct.default_capacity) as cap
      from days dy
      join public.template_slots ts on ts.template_id = t.id and ts.weekday = extract(isodow from dy.day)
      join public.class_types ct on ct.id = ts.class_type_id
  ), ins as (
    insert into public.class_sessions (class_type_id, template_id, starts_at, ends_at, capacity)
    select class_type_id, t.id, starts_at, starts_at + make_interval(mins => dur), cap
      from rows where starts_at > now()
    on conflict do nothing
    returning 1
  )
  select count(*) into n from ins;
  return n;
end $$;

-- Public availability (no personal data) for the schedule.
create or replace function public.session_availability(p_from timestamptz, p_to timestamptz)
returns table (
  id uuid, class_type_id uuid, type_slug text, type_name text, kind public.class_kind,
  credit_kind public.credit_kind, title text, description text, starts_at timestamptz, ends_at timestamptz,
  capacity int, spots_left int, waitlist_count int, price_cents int, location text, status public.session_status
)
language sql stable security definer set search_path = public as $$
  select s.id, s.class_type_id, ct.slug, ct.name, ct.kind, ct.credit_kind,
         coalesce(s.title, ct.name), coalesce(s.description, ct.description), s.starts_at, s.ends_at,
         s.capacity, greatest(s.capacity - public.spots_taken(s.id), 0),
         (select count(*)::int from public.waitlist_entries w where w.session_id = s.id and w.status in ('waiting','offered')),
         coalesce(s.price_cents, ct.price_cents), coalesce(s.location, ct.default_location), s.status
    from public.class_sessions s join public.class_types ct on ct.id = s.class_type_id
   where s.starts_at >= p_from and s.starts_at < p_to
   order by s.starts_at
$$;

-- Usable credits per kind for a profile.
create or replace function public.credit_balance(p_profile uuid)
returns table (credit_kind public.credit_kind, remaining int, next_expiry timestamptz)
language sql stable security definer set search_path = public as $$
  select l.credit_kind, sum(l.remaining)::int, min(l.expires_at)
    from public.credit_lots l
   where l.profile_id = p_profile and l.remaining > 0 and (l.expires_at is null or l.expires_at > now())
   group by l.credit_kind
$$;

-- ---------------------------------------------------------------------------
-- Auth glue: link/create a profile when a login account is created.
-- Clients added manually (from DMs or the CSV import) are matched by email.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  existing uuid;
begin
  select id into existing from public.profiles
   where lower(email) = lower(new.email) and user_id is null and deleted_at is null limit 1;
  if existing is not null then
    update public.profiles set user_id = new.id where id = existing;
  else
    insert into public.profiles (user_id, email) values (new.id, lower(new.email))
      on conflict do nothing;
  end if;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Right to erasure: strip personal data, keep the minimal booking/payment trail for accounting.
create or replace function public.erase_profile(p_profile uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid uuid;
begin
  select user_id into uid from public.profiles where id = p_profile;
  update public.bookings set status = 'cancelled', cancelled_at = now()
   where profile_id = p_profile and status in ('held', 'confirmed')
     and session_id in (select id from public.class_sessions where starts_at > now());
  update public.waitlist_entries set status = 'left' where profile_id = p_profile and status in ('waiting', 'offered');
  delete from public.health_notes where profile_id = p_profile;
  update public.profiles set full_name = 'Deleted client', email = null, phone = null, admin_notes = null,
         marketing_email = false, marketing_sms = false, user_id = null, deleted_at = now()
   where id = p_profile;
  update public.notifications set recipient = '[erased]', body = '[erased]' where profile_id = p_profile;
  return uid; -- caller deletes the auth user
end $$;

-- ---------------------------------------------------------------------------
-- Privileges: engine functions are server-only.
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.is_admin(), public.my_profile_id() to authenticated;
grant execute on function public.session_availability(timestamptz, timestamptz) to anon, authenticated;
grant execute on all functions in schema public to service_role;
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;


-- ===== 20261011000300_rls.sql =====
-- Row-level security. The app server uses the service role for writes; these
-- policies are defence in depth for anyone holding the public anon key.

alter table public.studio_settings enable row level security;
alter table public.profiles enable row level security;
alter table public.health_notes enable row level security;
alter table public.consents enable row level security;
alter table public.class_types enable row level security;
alter table public.timetable_templates enable row level security;
alter table public.template_slots enable row level security;
alter table public.class_sessions enable row level security;
alter table public.products enable row level security;
alter table public.payments enable row level security;
alter table public.credit_lots enable row level security;
alter table public.bookings enable row level security;
alter table public.credit_ledger enable row level security;
alter table public.waitlist_entries enable row level security;
alter table public.notifications enable row level security;
alter table public.otp_requests enable row level security;
alter table public.audit_log enable row level security;
alter table public.compliance_items enable row level security;

-- Public catalogue
create policy "public read settings" on public.studio_settings for select to anon, authenticated using (true);
create policy "public read class types" on public.class_types for select to anon, authenticated using (active or public.is_admin());
create policy "public read sessions" on public.class_sessions for select to anon, authenticated using (true);
create policy "public read products" on public.products for select to anon, authenticated using (active or public.is_admin());

-- Own records (+ admin)
create policy "own profile read" on public.profiles for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
create policy "own profile update" on public.profiles for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid() and role = 'client');
create policy "admin profile write" on public.profiles for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Health data: only the client themself and the instructor.
create policy "health owner or instructor" on public.health_notes for all to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin())
  with check (profile_id = public.my_profile_id() or public.is_admin());

create policy "own consents" on public.consents for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "own bookings" on public.bookings for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "own waitlist" on public.waitlist_entries for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "own credit lots" on public.credit_lots for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "own ledger" on public.credit_ledger for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "own payments" on public.payments for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());

-- Admin only
create policy "admin templates" on public.timetable_templates for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin slots" on public.template_slots for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin notifications" on public.notifications for select to authenticated using (public.is_admin());
create policy "admin audit" on public.audit_log for select to authenticated using (public.is_admin());
create policy "admin compliance" on public.compliance_items for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- otp_requests: no policies → service role only.


-- ===== 20261011000400_demo_seed.sql =====
-- Demo data as a function, so the admin "Reset demo data" button can rebuild it.
-- Everything is relative to now(), so the demo always looks current.
-- Demo clients are fictional (example.com addresses).

create or replace function public.seed_demo() returns void
language plpgsql security definer set search_path = public as $$
declare
  tz text := 'Europe/Nicosia';
  today date := (now() at time zone tz)::date;
  week_start date := date_trunc('week', (now() at time zone tz) + interval '1 day')::date;
  tpl uuid;
  reformer uuid;
  mat uuid;
  event_type uuid;
  cl uuid[] := '{}';
  pid uuid;
  elena uuid; maria uuid;
  lot_elena uuid; lot_maria uuid;
  memb uuid;
  monthly8 uuid;
  bid uuid;
  r record;
  idx int := 0;
  k int;
  j int;
  c uuid;
  is_past boolean;
  sup_day date;
  sid uuid;
  names text[] := array[
    'Elena Charalambous', 'Maria Georgiou', 'Sofia Andreou', 'Christina Michael', 'Niki Pavlou', 'Andria Ioannou',
    'Katerina Demetriou', 'Despina Kyriakou', 'Anna Petrou', 'Stella Constantinou', 'Myrto Hadjigeorgiou',
    'Rafaela Nicolaou', 'Ioanna Savva', 'Lucy Bennett', 'Daria Volkova', 'Georgia Antoniou'];
begin
  insert into public.studio_settings (id) values (1) on conflict do nothing;

  insert into public.class_types (slug, name, kind, credit_kind, description, default_capacity, default_duration_minutes, price_cents, default_location, sort_order) values
    ('reformer', 'Reformer Pilates', 'reformer', 'reformer',
     'Three reformers, one instructor. Strength, control and length, at your pace.', 3, 50, 2000, 'Re·Form Studio, Limassol', 1),
    ('mat', 'Mat Pilates', 'mat', 'mat',
     'Classical mat work for core, posture and breath. Mats and props provided.', 8, 50, 1500, 'Re·Form Studio, Limassol', 2),
    ('event', 'Special Event', 'event', null, 'One-off experiences outside the studio.', 8, 90, 3500, null, 3)
  on conflict (slug) do nothing;
  reformer := (select id from public.class_types where slug = 'reformer');
  mat := (select id from public.class_types where slug = 'mat');
  event_type := (select id from public.class_types where slug = 'event');

  if not exists (select 1 from public.products) then
    -- Placeholder prices until the studio confirms its packages. Validity runs from the first class.
    insert into public.products (name, kind, credit_kind, credits, price_cents, validity_days, period_days, description, is_group, active, sort_order) values
      ('Reformer · 4 classes', 'pack', 'reformer', 4, 7500, 30, null, 'Once a week for a month.', true, true, 1),
      ('Reformer · 8 classes', 'pack', 'reformer', 8, 14000, 30, null, 'Twice a week. Our most popular.', true, true, 2),
      ('Reformer · 12 classes', 'pack', 'reformer', 12, 19500, 60, null, 'Your own pace over two months.', true, true, 3),
      ('Mat · 5 classes', 'pack', 'mat', 5, 6500, 30, null, 'Mat Pilates for a month.', true, true, 4),
      -- Auto-renewing monthly package: code kept behind the online-payments flag, hidden for now.
      ('Monthly · 8 reformer classes', 'membership', 'reformer', 8, 14000, null, 30, 'Renews every 30 days.', true, false, 9);
  end if;
  monthly8 := (select id from public.products where name = 'Monthly · 8 reformer classes' limit 1);

  insert into public.compliance_items (key) values
    ('privacy_policy_reviewed'), ('terms_reviewed'), ('cancellation_policy_reviewed'), ('withdrawal_right_confirmed'),
    ('health_disclaimer_reviewed'), ('business_details_filled'), ('cookie_policy_reviewed'), ('no_nonessential_cookies'),
    ('health_consent_flow_tested'), ('data_export_tested'), ('account_deletion_tested'), ('consent_log_verified'),
    ('marketing_opt_in_only'), ('dpa_supabase'), ('dpa_stripe'), ('dpa_resend'), ('dpa_twilio'), ('dpa_vercel'),
    ('supabase_eu_region'), ('supabase_backups_enabled'), ('rls_verified'), ('admin_roles_verified'), ('otp_rate_limit_verified'),
    ('https_only'), ('demo_mode_off'), ('stripe_live_keys'), ('apple_pay_domain_verified'), ('contrast_checked'),
    ('keyboard_screenreader_tested'), ('reduced_motion_tested'), ('alt_text_reviewed'), ('photos_permission'),
    ('no_unsupported_claims'), ('fonts_licensed'), ('retention_job_scheduled'),
    ('pay_registered_self_employed'), ('pay_vat_position_confirmed'), ('pay_bank_stripe_verified'),
    ('pay_legal_texts_reviewed'), ('pay_liability_insurance')
  on conflict do nothing;

  -- The posted weekly reformer timetable: two weeks of history + three weeks ahead.
  insert into public.timetable_templates (name, valid_from, valid_to)
    values (trim(to_char(now() at time zone tz, 'Month YYYY')) || ' timetable', week_start - 14, week_start + 20)
    returning id into tpl;
  insert into public.template_slots (template_id, weekday, start_time, class_type_id)
  select tpl, d, t::time, reformer from (values
    (1, '08:00'), (1, '09:00'), (1, '17:30'), (1, '18:30'), (1, '19:30'),
    (2, '07:00'), (2, '08:00'), (2, '16:00'), (2, '17:00'), (2, '18:00'), (2, '19:00'),
    (3, '07:30'), (3, '08:30'), (3, '16:00'), (3, '17:00'),
    (4, '08:00'), (4, '09:00'), (4, '16:30'), (4, '17:30'), (4, '18:30'), (4, '19:30'),
    (5, '08:00'), (5, '16:00'), (5, '17:00'), (5, '18:00'), (5, '19:00')
  ) as v(d, t);
  perform public.generate_sessions(tpl);
  -- generate_sessions only creates future classes; add the past ones for history.
  insert into public.class_sessions (class_type_id, template_id, starts_at, ends_at, capacity)
  select ts.class_type_id, tpl, (dy + ts.start_time) at time zone tz, (dy + ts.start_time) at time zone tz + interval '50 minutes', 3
    from generate_series(week_start - 14, today, interval '1 day') g(dy0)
    cross join lateral (select g.dy0::date as dy) x
    join public.template_slots ts on ts.template_id = tpl and ts.weekday = extract(isodow from x.dy)
   where (x.dy + ts.start_time) at time zone tz < now()
  on conflict do nothing;

  -- Clients
  foreach pid in array array[]::uuid[] loop end loop;
  for j in 1 .. array_length(names, 1) loop
    insert into public.profiles (full_name, email, phone, onboarded_at, created_at)
      values (names[j], lower(split_part(names[j], ' ', 1)) || '@example.com', '+357 99 ' || lpad((100000 + j * 7919)::text, 6, '0'),
              now() - make_interval(days => 60 - j * 3), now() - make_interval(days => 60 - j * 3))
      returning id into pid;
    cl := cl || pid;
    insert into public.consents (profile_id, type, granted, version, created_at)
    select pid, t::public.consent_type, true, '2026-10-v1', now() - make_interval(days => 60 - j * 3)
      from unnest(array['policy', 'terms', 'fitness_declaration']) t;
  end loop;
  elena := cl[1]; maria := cl[2];
  update public.profiles set admin_notes = 'Prefers evening classes. Came via Instagram DM.' where id = cl[6];
  update public.profiles set marketing_email = true where id in (cl[1], cl[3], cl[7]);
  insert into public.health_notes (profile_id, note, consent_at) values
    (maria, 'Mild lower-back sensitivity. Avoid deep spinal flexion on bad days.', now() - interval '50 days'),
    (cl[9], '20 weeks pregnant. Cleared by her doctor; no supine work after the first trimester.', now() - interval '20 days');
  insert into public.consents (profile_id, type, granted, version) values (maria, 'health_data', true, '2026-10-v1'), (cl[9], 'health_data', true, '2026-10-v1');

  -- Elena: 8-class pack paid in cash; validity started with her first class (18 days ago).
  insert into public.payments (profile_id, provider, amount_cents, purpose, description, status, method, product_id, paid_at, created_at)
    select elena, 'offline', price_cents, 'pack', name, 'paid', 'revolut', id, now() - interval '20 days', now() - interval '20 days'
      from public.products where name = 'Reformer · 8 classes' returning id into bid;
  lot_elena := public.grant_lot(elena, 'reformer', 8, null, 'Reformer · 8 classes', bid, null, null, 'grant', null, 30);
  -- One-off packs for others (granted through the ledger).
  lot_maria := public.grant_lot(maria, 'reformer', 4, null, 'Reformer · 4 classes (not started yet)', null, null, null, 'grant', null, 30);
  perform public.grant_lot(cl[3], 'reformer', 2, now() + interval '4 days', 'Reformer · 8 classes (2 left)');
  perform public.grant_lot(cl[7], 'reformer', 6, now() + interval '41 days', 'Reformer · 12 classes (6 left)');
  perform public.grant_lot(cl[12], 'mat', 1, now() + interval '20 days', 'Mat · 5 classes (1 left)');
  update public.profiles set student_verified_until = (now() + interval '8 months')::date where id in (cl[13], cl[15]);

  -- Elena's usual slot: Tuesday 18:00 (history + next week booked), so "Your next class"
  -- and "Rebook your usual" have something to show when signing in as elena@example.com.
  for r in select s.id, s.starts_at from public.class_sessions s
            where s.class_type_id = reformer and extract(isodow from s.starts_at at time zone tz) = 2
              and to_char(s.starts_at at time zone tz, 'HH24:MI') = '18:00'
            order by s.starts_at
  loop
    is_past := r.starts_at < now();
    if (is_past and r.starts_at > now() - interval '18 days') or (not is_past and r.starts_at < now() + interval '8 days') then
      insert into public.bookings (session_id, profile_id, status, paid_with, credit_lot_id, confirmed_at, checked_in_at, created_at)
        values (r.id, elena, 'confirmed', 'credit', lot_elena, r.starts_at - interval '3 days', case when is_past then r.starts_at end, r.starts_at - interval '3 days')
        returning id into bid;
      perform public.spend_credits(elena, 'reformer', 1, bid, r.starts_at);
    elsif is_past then
      insert into public.bookings (session_id, profile_id, status, paid_with, confirmed_at, checked_in_at, created_at)
        values (r.id, elena, 'confirmed', 'manual', r.starts_at - interval '3 days', r.starts_at, r.starts_at - interval '3 days');
    end if;
  end loop;

  -- Ledger rows were written "now"; date them like the real bookings so history reads naturally.
  perform set_config('reform.ledger_maintenance', 'on', true);
  update public.credit_ledger g set created_at = b.created_at from public.bookings b where g.booking_id = b.id;
  update public.credit_ledger g set created_at = p.paid_at from public.credit_lots l join public.payments p on p.id = l.payment_id
   where g.lot_id = l.id and g.entry_type = 'grant' and p.paid_at is not null;
  perform set_config('reform.ledger_maintenance', 'off', true);

  -- Everyone else: a realistic mix of full, "1 left", quiet and empty classes, with waitlists.
  for r in select s.id, s.starts_at, s.capacity,
                  (select count(*) from public.bookings b where b.session_id = s.id)::int as taken
             from public.class_sessions s where s.class_type_id = reformer order by s.starts_at
  loop
    idx := idx + 1;
    is_past := r.starts_at < now();
    k := case
           when is_past then 1 + (idx % 3)                                -- history: 1–3 people
           when r.starts_at < now() + interval '30 hours' then 1 + (idx % 3)
           else (array[3, 2, 0, 1, 2, 3, 1, 0, 2, 1, 3, 1])[1 + idx % 12]  -- ahead: full / 1 left / quiet / empty
         end;
    k := least(k, r.capacity) - r.taken;
    for j in 0 .. k - 1 loop
      c := cl[2 + ((idx * 5 + j * 3) % (array_length(cl, 1) - 1))];      -- never Elena (handled above)
      continue when exists (select 1 from public.bookings b where b.session_id = r.id and b.profile_id = c);
      insert into public.bookings (session_id, profile_id, status, paid_with, source, confirmed_at, checked_in_at, created_at)
        values (r.id, c,
                case when is_past and idx % 11 = 0 and j = 0 then 'no_show' else 'confirmed' end::public.booking_status,
                case when j = 0 and idx % 4 = 0 then 'payment' else 'manual' end::public.paid_with,
                case when idx % 3 = 0 then 'manual' else 'online' end::public.booking_source,
                r.starts_at - make_interval(days => 1 + idx % 5),
                case when is_past and not (idx % 11 = 0 and j = 0) then r.starts_at + interval '2 minutes' end,
                r.starts_at - make_interval(days => 1 + idx % 5));
    end loop;
    -- Waitlists on some full upcoming classes
    if not is_past and r.starts_at > now() + interval '30 hours'
       and (select count(*) from public.bookings b where b.session_id = r.id and b.status = 'confirmed') >= r.capacity
       and idx % 2 = 0 then
      for j in 0 .. (idx % 3) loop
        c := cl[2 + ((idx * 7 + j * 5 + 1) % (array_length(cl, 1) - 1))];
        continue when exists (select 1 from public.bookings b where b.session_id = r.id and b.profile_id = c)
                   or exists (select 1 from public.waitlist_entries w where w.session_id = r.id and w.profile_id = c);
        insert into public.waitlist_entries (session_id, profile_id, created_at) values (r.id, c, now() - make_interval(hours => 5 - j));
      end loop;
    end if;
  end loop;

  -- Two upcoming "pay at the studio" bookings (unpaid) so the roster shows the flag.
  for r in select b.id, b.profile_id, b.session_id from public.bookings b join public.class_sessions x on x.id = b.session_id
            where b.status = 'confirmed' and b.paid_with = 'manual' and b.profile_id in (cl[4], cl[11]) and x.starts_at > now()
            order by x.starts_at limit 2
  loop
    insert into public.payments (profile_id, provider, amount_cents, purpose, description, booking_id, status)
      values (r.profile_id, 'offline', 2000, 'booking', 'Reformer Pilates (pay at studio)', r.id, 'pending') returning id into bid;
    update public.bookings set paid_with = 'pay_at_studio', payment_id = bid where id = r.id;
  end loop;
  -- A pending pack request waiting for payment at the studio.
  insert into public.payments (profile_id, provider, amount_cents, purpose, description, status, product_id)
    select cl[5], 'offline', price_cents, 'pack', name, 'pending', id from public.products where name = 'Reformer · 8 classes' limit 1;

  -- Saturday: a mat class and a SUP Pilates event on the beach
  sup_day := today + ((6 - extract(isodow from today)::int + 7) % 7);
  if sup_day < today + 2 then sup_day := sup_day + 7; end if;

  insert into public.class_sessions (class_type_id, starts_at, ends_at, capacity)
    values (mat, (sup_day + time '11:00') at time zone tz, (sup_day + time '11:50') at time zone tz, 8) returning id into sid;
  insert into public.bookings (session_id, profile_id, status, paid_with, confirmed_at)
    select sid, unnest(array[cl[12], cl[5], cl[14]]), 'confirmed', 'manual', now() - interval '1 day';

  insert into public.class_sessions (class_type_id, title, description, starts_at, ends_at, capacity, price_cents, location)
    values (event_type, 'SUP Pilates', 'Pilates on a paddle board at sunrise. Boards and paddles provided. No experience needed, just bring a towel and water.',
            (sup_day + time '08:30') at time zone tz, (sup_day + time '10:00') at time zone tz, 8, 3500,
            'Beach, Limassol (exact spot shared after booking)')
    returning id into sid;
  insert into public.bookings (session_id, profile_id, status, paid_with, confirmed_at)
    select sid, unnest(array[cl[3], cl[6], cl[8], cl[10], cl[13]]), 'confirmed', 'manual', now() - interval '2 days';

  -- A few historical online payments so Stats has revenue
  insert into public.payments (profile_id, provider, amount_cents, purpose, description, status, method, paid_at, created_at)
  values (maria, 'offline', 7500, 'pack', 'Reformer · 4 classes', 'paid', 'bank_transfer', now() - interval '2 days', now() - interval '2 days'),
         (cl[7], 'offline', 19500, 'pack', 'Reformer · 12 classes', 'paid', 'revolut', now() - interval '19 days', now() - interval '19 days'),
         (cl[3], 'offline', 14000, 'pack', 'Reformer · 8 classes', 'paid', 'cash', now() - interval '26 days', now() - interval '26 days');
end $$;

-- ("where true": PostgREST's safeupdate rejects unqualified DELETE/UPDATE.)
-- Wipes bookings/clients and rebuilds the demo. Keeps admins, settings, class types and products.
create or replace function public.reset_demo_data() returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from public.notifications where true;
  delete from public.waitlist_entries where true;
  delete from public.credit_ledger where true;
  update public.bookings set credit_lot_id = null, payment_id = null where true;
  update public.payments set booking_id = null where true;
  delete from public.bookings where true;
  delete from public.credit_lots where true;
  delete from public.payments where true;
  delete from public.class_sessions where true;
  delete from public.timetable_templates where true;
  delete from public.otp_requests where true;
  delete from public.consents where profile_id in (select id from public.profiles where role = 'client');
  delete from public.profiles where role = 'client';
  perform public.seed_demo();
end $$;

revoke execute on function public.seed_demo(), public.reset_demo_data() from public, anon, authenticated;
grant execute on function public.seed_demo(), public.reset_demo_data() to service_role;


-- ===== 20261011000500_rls_hardening.sql =====
-- Security review hardening: all writes go through the server (service role).
-- Clients holding the public anon key can only READ their own rows.

drop policy if exists "own profile update" on public.profiles;
drop policy if exists "health owner or instructor" on public.health_notes;

-- Health data (GDPR art. 9): the client can read their own note; only the
-- instructor (admin) can read all. Writes happen server-side so consent is logged.
create policy "health read owner or instructor" on public.health_notes for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
create policy "health instructor write" on public.health_notes for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Belt and braces: anon/authenticated never write these tables directly.
revoke insert, update, delete on public.profiles, public.consents, public.bookings, public.waitlist_entries,
  public.credit_lots, public.credit_ledger, public.payments, public.notifications, public.otp_requests,
  public.audit_log, public.class_sessions, public.class_types, public.products, public.studio_settings
  from anon, authenticated;
revoke all on public.otp_requests, public.audit_log from anon, authenticated;


-- ===== 20261011000600_payments_memberships.sql =====
-- Payments behind a flag (pay at the studio while unregistered), monthly packages
-- (memberships), append-only credit ledger with typed entries, per-class credit cost.

-- ---------------------------------------------------------------------------
-- Types & columns
-- ---------------------------------------------------------------------------
alter type public.paid_with add value if not exists 'pay_at_studio';
alter type public.product_kind add value if not exists 'membership';
create type public.membership_status as enum ('active', 'paused', 'past_due', 'cancelled', 'expired');
create type public.ledger_entry as enum ('grant', 'booking_debit', 'cancel_refund', 'expiry', 'admin_adjustment', 'rollover');

alter table public.studio_settings
  add column online_payments_enabled boolean not null default false,
  add column allow_pay_later boolean not null default true,
  add column membership_period_mode text not null default 'rolling' check (membership_period_mode in ('rolling', 'calendar')),
  add column rollover_max int not null default 0 check (rollover_max between 0 and 50),
  add column trader_name text not null default '[Owner full name]';
-- Not registered yet: trading name only; VAT/registration stay empty and hidden.
alter table public.studio_settings alter column legal_name set default 'Re·Form Pilates Studio';
update public.studio_settings set legal_name = 'Re·Form Pilates Studio', registration_number = '', vat_number = '', vat_registered = false;
alter table public.studio_settings alter column registration_number set default '';
alter table public.studio_settings alter column vat_number set default '';

alter table public.class_types add column credit_cost int not null default 1 check (credit_cost between 1 and 10);

alter table public.products
  add column period_days int check (period_days between 7 and 366),
  add column description text;

alter table public.profiles add column stripe_customer_id text unique;

create table public.memberships (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null references public.profiles(id) on delete cascade,
  product_id uuid not null references public.products(id),
  next_product_id uuid references public.products(id),        -- change applies from the next period
  status public.membership_status not null default 'active',
  provider text not null default 'offline' check (provider in ('offline', 'stripe')),
  provider_subscription_id text unique,
  current_period_start timestamptz not null,
  current_period_end timestamptz not null,
  cancel_at_period_end boolean not null default false,
  paused_at timestamptz,
  created_at timestamptz not null default now()
);
create index memberships_profile_idx on public.memberships (profile_id, status);
create unique index memberships_one_live on public.memberships (profile_id) where status in ('active', 'paused', 'past_due');

alter table public.credit_lots
  add column membership_id uuid references public.memberships(id) on delete set null,
  add column period_start timestamptz;
create unique index credit_lots_one_per_period on public.credit_lots (membership_id, period_start) where membership_id is not null;

alter table public.payments
  add column method text check (method in ('online', 'cash', 'card_in_person', 'bank_transfer')),
  add column membership_id uuid references public.memberships(id) on delete set null;
alter table public.payments drop constraint if exists payments_purpose_check;
alter table public.payments add constraint payments_purpose_check check (purpose in ('booking', 'pack', 'membership', 'renewal'));

-- Stripe webhook idempotency
create table public.processed_webhooks (id text primary key, created_at timestamptz not null default now());

-- Ledger: typed entries, a note, and append-only.
alter table public.credit_ledger rename column reason to entry_type_old;
alter table public.credit_ledger add column entry_type public.ledger_entry, add column note text, add column actor_profile_id uuid references public.profiles(id) on delete set null;
update public.credit_ledger set entry_type = case entry_type_old
  when 'purchase' then 'grant' when 'import' then 'grant' when 'booking' then 'booking_debit'
  when 'admin_adjust' then 'admin_adjustment' else 'cancel_refund' end::public.ledger_entry,
  note = entry_type_old;
alter table public.credit_ledger drop column entry_type_old;
alter table public.credit_ledger alter column entry_type set not null;
alter table public.credit_ledger add constraint ledger_admin_reason check (entry_type <> 'admin_adjustment' or coalesce(trim(note), '') <> '');

create or replace function public.ledger_append_only() returns trigger
language plpgsql as $$
begin
  if coalesce(current_setting('reform.ledger_maintenance', true), '') = 'on' then
    return coalesce(new, old);
  end if;
  raise exception 'credit_ledger is append-only';
end $$;
create trigger credit_ledger_append_only before update or delete on public.credit_ledger
  for each row execute function public.ledger_append_only();

alter table public.memberships enable row level security;
alter table public.processed_webhooks enable row level security;
create policy "own memberships" on public.memberships for select to authenticated
  using (profile_id = public.my_profile_id() or public.is_admin());
revoke insert, update, delete on public.memberships from anon, authenticated;
revoke all on public.processed_webhooks from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Credit primitives. credit_lots.remaining is a cache kept in lock-step with the
-- ledger by these functions only; the ledger is the source of truth.
-- ---------------------------------------------------------------------------
create or replace function public.grant_lot(
  p_profile uuid, p_kind public.credit_kind, p_credits int, p_expires timestamptz, p_note text,
  p_payment uuid default null, p_membership uuid default null, p_period_start timestamptz default null,
  p_entry public.ledger_entry default 'grant', p_actor uuid default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  lot uuid;
begin
  insert into public.credit_lots (profile_id, credit_kind, total, remaining, expires_at, payment_id, note, membership_id, period_start)
    values (p_profile, p_kind, p_credits, p_credits, p_expires, p_payment, p_note, p_membership, p_period_start)
    on conflict (membership_id, period_start) where membership_id is not null do nothing
    returning id into lot;
  if lot is null then return null; end if; -- already granted for this period (idempotent)
  insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, note, actor_profile_id)
    values (p_profile, lot, p_kind, p_credits, p_entry, p_note, p_actor);
  return lot;
end $$;

-- Spend credits oldest-expiring first, possibly across several lots. Locks the lots.
create or replace function public.spend_credits(p_profile uuid, p_kind public.credit_kind, p_cost int, p_booking uuid, p_valid_at timestamptz)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  need int := p_cost;
  lot record;
  take int;
  first_lot uuid;
  available int;
begin
  select coalesce(sum(remaining), 0) into available from public.credit_lots
   where profile_id = p_profile and credit_kind = p_kind and remaining > 0 and (expires_at is null or expires_at > p_valid_at);
  if available < p_cost then raise exception 'no_credits' using errcode = 'P0001'; end if;

  for lot in select id, remaining from public.credit_lots
              where profile_id = p_profile and credit_kind = p_kind and remaining > 0
                and (expires_at is null or expires_at > p_valid_at)
              order by expires_at nulls last, created_at
              for update
  loop
    exit when need = 0;
    take := least(need, lot.remaining);
    update public.credit_lots set remaining = remaining - take where id = lot.id;
    insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, booking_id)
      values (p_profile, lot.id, p_kind, -take, 'booking_debit', p_booking);
    first_lot := coalesce(first_lot, lot.id);
    need := need - take;
  end loop;
  if need > 0 then raise exception 'no_credits' using errcode = 'P0001'; end if;
  return first_lot;
end $$;

-- Expire unused credits (ledger 'expiry' entries). Run from the periodic tick.
create or replace function public.expire_credits() returns int
language plpgsql security definer set search_path = public as $$
declare
  lot record;
  n int := 0;
begin
  for lot in select * from public.credit_lots where remaining > 0 and expires_at is not null and expires_at <= now() for update skip locked
  loop
    insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, note)
      values (lot.profile_id, lot.id, lot.credit_kind, -lot.remaining, 'expiry', lot.note);
    update public.credit_lots set remaining = 0 where id = lot.id;
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.admin_adjust_credits(p_profile uuid, p_kind public.credit_kind, p_delta int, p_days int, p_reason text, p_actor uuid)
returns void
language plpgsql security definer set search_path = public as $$
begin
  if coalesce(trim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
  if p_delta > 0 then
    perform public.grant_lot(p_profile, p_kind, p_delta,
      case when p_days > 0 then now() + make_interval(days => p_days) end, p_reason, null, null, null, 'admin_adjustment', p_actor);
  elsif p_delta < 0 then
    -- Remove from the soonest-expiring lots.
    declare need int := -p_delta; lot record; take int;
    begin
      for lot in select id, remaining from public.credit_lots
                  where profile_id = p_profile and credit_kind = p_kind and remaining > 0 and (expires_at is null or expires_at > now())
                  order by expires_at nulls last for update
      loop
        exit when need = 0;
        take := least(need, lot.remaining);
        update public.credit_lots set remaining = remaining - take where id = lot.id;
        insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, note, actor_profile_id)
          values (p_profile, lot.id, p_kind, -take, 'admin_adjustment', p_reason, p_actor);
        need := need - take;
      end loop;
      if need > 0 then raise exception 'not_enough_credits' using errcode = 'P0001'; end if;
    end;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Refunds: reverse a booking's debits back to the same lots (original expiry).
-- ---------------------------------------------------------------------------
create or replace function public.return_credit(p_booking uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare
  b public.bookings;
  kind public.credit_kind;
  cost int;
  d record;
begin
  select * into b from public.bookings where id = p_booking;
  select ct.credit_kind, ct.credit_cost into kind, cost
    from public.class_sessions s join public.class_types ct on ct.id = s.class_type_id where s.id = b.session_id;

  if b.paid_with = 'credit' then
    for d in select lot_id, credit_kind, sum(delta) as spent from public.credit_ledger
              where booking_id = b.id and entry_type in ('booking_debit', 'cancel_refund') and lot_id is not null
              group by lot_id, credit_kind having sum(delta) < 0
    loop
      update public.credit_lots set remaining = remaining - d.spent where id = d.lot_id;
      insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, booking_id, note)
        values (b.profile_id, d.lot_id, d.credit_kind, -d.spent, 'cancel_refund', b.id, p_reason);
    end loop;
  elsif b.paid_with = 'payment' then
    if kind is null then
      update public.payments set status = 'needs_refund' where id = b.payment_id and status = 'paid';
    else
      -- Paid for a single class: becomes class credit(s) of that type, valid 30 days.
      perform public.grant_lot(b.profile_id, kind, cost, now() + interval '30 days', 'Credit for cancelled class', b.payment_id, null, null, 'cancel_refund');
    end if;
  elsif b.paid_with = 'pay_at_studio' then
    update public.payments set status = 'cancelled' where id = b.payment_id and status = 'pending';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Booking (adds per-class credit cost and pay-at-studio)
-- ---------------------------------------------------------------------------
create or replace function public.book_session(
  p_profile uuid, p_session uuid, p_mode text, p_source public.booking_source default 'online'
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.class_sessions;
  ct public.class_types;
  cfg public.studio_settings := public.settings();
  new_id uuid;
  first_lot uuid;
  pay_id uuid;
  st public.booking_status;
begin
  select * into s from public.class_sessions where id = p_session for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if s.status <> 'scheduled' then raise exception 'class_cancelled' using errcode = 'P0001'; end if;
  if p_source = 'online' and s.starts_at <= now() then raise exception 'class_started' using errcode = 'P0001'; end if;
  if p_source = 'manual' and s.ends_at <= now() - interval '1 day' then raise exception 'class_past' using errcode = 'P0001'; end if;
  select * into ct from public.class_types where id = s.class_type_id;

  update public.bookings set status = 'expired'
   where session_id = p_session and status = 'held' and hold_expires_at <= now();
  if exists (select 1 from public.bookings where session_id = p_session and profile_id = p_profile and status in ('held','confirmed')) then
    raise exception 'already_booked' using errcode = 'P0001';
  end if;
  if public.spots_taken(p_session, p_profile) >= s.capacity then
    raise exception 'full' using errcode = 'P0001';
  end if;

  if p_mode = 'credit' then
    if ct.credit_kind is null then raise exception 'credits_not_accepted' using errcode = 'P0001'; end if;
    insert into public.bookings (session_id, profile_id, status, source, paid_with, confirmed_at)
      values (p_session, p_profile, 'confirmed', p_source, 'credit', now()) returning id into new_id;
    first_lot := public.spend_credits(p_profile, ct.credit_kind, ct.credit_cost, new_id, s.starts_at);
    update public.bookings set credit_lot_id = first_lot where id = new_id;
    st := 'confirmed';
  elsif p_mode = 'payment' then
    if not cfg.online_payments_enabled and p_source = 'online' then raise exception 'online_payments_off' using errcode = 'P0001'; end if;
    insert into public.bookings (session_id, profile_id, status, source, hold_expires_at)
      values (p_session, p_profile, 'held', p_source, now() + make_interval(mins => cfg.hold_minutes)) returning id into new_id;
    st := 'held';
  elsif p_mode = 'pay_at_studio' then
    if p_source = 'online' then
      if not cfg.allow_pay_later then raise exception 'pay_later_off' using errcode = 'P0001'; end if;
      -- At most one unpaid upcoming class at a time.
      if exists (select 1 from public.bookings b join public.class_sessions x on x.id = b.session_id
                  where b.profile_id = p_profile and b.status = 'confirmed' and b.paid_with = 'pay_at_studio' and x.ends_at > now()) then
        raise exception 'unpaid_limit' using errcode = 'P0001';
      end if;
    end if;
    insert into public.bookings (session_id, profile_id, status, source, paid_with, confirmed_at)
      values (p_session, p_profile, 'confirmed', p_source, 'pay_at_studio', now()) returning id into new_id;
    insert into public.payments (profile_id, provider, amount_cents, purpose, description, booking_id, status)
      values (p_profile, 'offline', coalesce(s.price_cents, ct.price_cents), 'booking',
              coalesce(s.title, ct.name) || ' · ' || to_char(s.starts_at at time zone cfg.timezone, 'Dy DD Mon HH24:MI'), new_id, 'pending')
      returning id into pay_id;
    update public.bookings set payment_id = pay_id where id = new_id;
    st := 'confirmed';
  elsif p_mode in ('manual', 'free') then
    insert into public.bookings (session_id, profile_id, status, source, paid_with, confirmed_at)
      values (p_session, p_profile, 'confirmed', p_source, p_mode::public.paid_with, now()) returning id into new_id;
    st := 'confirmed';
  else
    raise exception 'bad_mode' using errcode = 'P0001';
  end if;

  update public.waitlist_entries set status = 'claimed'
   where session_id = p_session and profile_id = p_profile and status in ('waiting', 'offered');
  if st = 'confirmed' then perform public.apply_late_fill_refund(p_session); end if;
  return jsonb_build_object('booking_id', new_id, 'status', st);
end $$;

-- ---------------------------------------------------------------------------
-- Memberships
-- ---------------------------------------------------------------------------
create or replace function public.period_end(p_start timestamptz, p_days int) returns timestamptz
language sql stable security definer set search_path = public as $$
  select case when (public.settings()).membership_period_mode = 'calendar'
              then (date_trunc('month', p_start at time zone (public.settings()).timezone) + interval '1 month') at time zone (public.settings()).timezone
              else p_start + make_interval(days => coalesce(p_days, 30)) end
$$;

-- Grant one period's credits (idempotent per membership + period start), with rollover.
create or replace function public.grant_membership_period(p_membership uuid, p_start timestamptz, p_payment uuid default null)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  m public.memberships;
  prod public.products;
  cfg public.studio_settings := public.settings();
  p_end timestamptz;
  lot uuid;
  prev public.credit_lots;
  carry int := 0;
begin
  select * into m from public.memberships where id = p_membership for update;
  -- A scheduled package change takes effect from this period.
  if m.next_product_id is not null and p_start >= m.current_period_end then
    update public.memberships set product_id = next_product_id, next_product_id = null where id = m.id returning * into m;
  end if;
  select * into prod from public.products where id = m.product_id;
  p_end := public.period_end(p_start, prod.period_days);

  lot := public.grant_lot(m.profile_id, prod.credit_kind, prod.credits, p_end, prod.name, p_payment, m.id, p_start);
  if lot is null then
    return (select id from public.credit_lots where membership_id = m.id and period_start = p_start);
  end if;

  -- Rollover: carry up to N unused credits from the previous period into this one.
  if cfg.rollover_max > 0 then
    select * into prev from public.credit_lots
     where membership_id = m.id and period_start < p_start and remaining > 0
     order by period_start desc limit 1 for update;
    if found then
      carry := least(prev.remaining, cfg.rollover_max);
      update public.credit_lots set remaining = remaining - carry where id = prev.id;
      insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, note)
        values (m.profile_id, prev.id, prev.credit_kind, -carry, 'rollover', 'Rolled into next period');
      update public.credit_lots set remaining = remaining + carry, total = total + carry where id = lot;
      insert into public.credit_ledger (profile_id, lot_id, credit_kind, delta, entry_type, note)
        values (m.profile_id, lot, prev.credit_kind, carry, 'rollover', 'Rolled over from last period');
    end if;
  end if;

  update public.memberships
     set current_period_start = p_start, current_period_end = p_end,
         status = case when status in ('past_due', 'expired') then 'active' else status end
   where id = m.id;
  return lot;
end $$;

create or replace function public.pause_membership(p_membership uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.memberships set status = 'paused', paused_at = now() where id = p_membership and status = 'active';
end $$;

-- Resume: the period and its credits are extended by the time spent paused.
create or replace function public.resume_membership(p_membership uuid) returns interval
language plpgsql security definer set search_path = public as $$
declare
  m public.memberships;
  gap interval;
begin
  select * into m from public.memberships where id = p_membership and status = 'paused' for update;
  if not found then return interval '0'; end if;
  gap := now() - m.paused_at;
  update public.memberships set status = 'active', paused_at = null, current_period_end = current_period_end + gap where id = m.id;
  update public.credit_lots set expires_at = expires_at + gap
   where membership_id = m.id and period_start = m.current_period_start and expires_at is not null;
  return gap;
end $$;

-- ---------------------------------------------------------------------------
-- Payment confirmation (online webhook OR "Mark as paid" in the studio)
-- ---------------------------------------------------------------------------
create or replace function public.confirm_payment(p_payment uuid, p_provider_ref text default null, p_method text default 'online')
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  p public.payments;
  b public.bookings;
  s public.class_sessions;
  prod public.products;
  m public.memberships;
  lot_id uuid;
  start_at timestamptz;
begin
  select * into p from public.payments where id = p_payment for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p.status = 'paid' then return jsonb_build_object('status', 'already_paid', 'booking_id', p.booking_id); end if;
  if p.status in ('cancelled', 'refunded') then raise exception 'payment_cancelled' using errcode = 'P0001'; end if;

  update public.payments set status = 'paid', paid_at = now(), method = p_method,
         provider_ref = coalesce(p_provider_ref, provider_ref)
   where id = p.id;

  if p.purpose = 'pack' then
    select * into prod from public.products where id = p.product_id;
    lot_id := public.grant_lot(p.profile_id, prod.credit_kind, prod.credits,
      case when prod.validity_days is null then null else now() + make_interval(days => prod.validity_days) end, prod.name, p.id);
    return jsonb_build_object('status', 'credits_added', 'lot_id', lot_id);
  end if;

  if p.purpose in ('membership', 'renewal') then
    select * into prod from public.products where id = p.product_id;
    if p.membership_id is null then
      insert into public.memberships (profile_id, product_id, provider, current_period_start, current_period_end)
        values (p.profile_id, prod.id, case when p.provider = 'stripe' then 'stripe' else 'offline' end, now(), public.period_end(now(), prod.period_days))
        returning * into m;
      update public.payments set membership_id = m.id where id = p.id;
      start_at := m.current_period_start;
    else
      select * into m from public.memberships where id = p.membership_id;
      -- Renewal: next period starts when the current one ends (or now, if it has lapsed).
      start_at := greatest(m.current_period_end, now());
      if p.purpose = 'membership' then start_at := m.current_period_start; end if;
    end if;
    lot_id := public.grant_membership_period(m.id, start_at, p.id);
    return jsonb_build_object('status', 'membership_active', 'membership_id', m.id, 'lot_id', lot_id);
  end if;

  select * into b from public.bookings where id = p.booking_id for update;
  select * into s from public.class_sessions where id = b.session_id for update;

  if b.status = 'confirmed' then
    -- Pay-at-studio booking settled in person.
    update public.bookings set paid_with = 'payment', payment_id = p.id where id = b.id and paid_with = 'pay_at_studio';
    return jsonb_build_object('status', 'confirmed', 'booking_id', b.id);
  end if;

  if s.status = 'scheduled' and (
       (b.status = 'held' and b.hold_expires_at > now())
       or public.spots_taken(s.id, b.profile_id) < s.capacity
     ) and not exists (
       select 1 from public.bookings x where x.session_id = s.id and x.profile_id = b.profile_id
        and x.status = 'confirmed' and x.id <> b.id)
  then
    update public.bookings set status = 'confirmed', paid_with = 'payment', payment_id = p.id,
           hold_expires_at = null, confirmed_at = now()
     where id = b.id;
    perform public.apply_late_fill_refund(s.id);
    return jsonb_build_object('status', 'confirmed', 'booking_id', b.id);
  end if;

  update public.bookings set status = 'expired', payment_id = p.id where id = b.id;
  update public.payments set status = 'needs_refund' where id = p.id;
  return jsonb_build_object('status', 'needs_refund', 'booking_id', b.id);
end $$;

drop function if exists public.confirm_payment(uuid, text);

-- Late-fill refund now uses the ledger-based return_credit (unchanged signature).
-- Studio reset needs to clear the append-only ledger.
create or replace function public.reset_demo_data() returns void
language plpgsql security definer set search_path = public as $$
begin
  perform set_config('reform.ledger_maintenance', 'on', true);
  delete from public.notifications where true;
  delete from public.waitlist_entries where true;
  delete from public.credit_ledger where true;
  update public.bookings set credit_lot_id = null, payment_id = null where true;
  update public.payments set booking_id = null, membership_id = null where true;
  delete from public.bookings where true;
  delete from public.credit_lots where true;
  delete from public.payments where true;
  delete from public.memberships where true;
  delete from public.class_sessions where true;
  delete from public.timetable_templates where true;
  delete from public.otp_requests where true;
  delete from public.processed_webhooks where true;
  delete from public.consents where profile_id in (select id from public.profiles where role = 'client');
  delete from public.profiles where role = 'client';
  delete from public.products where true;
  perform public.seed_demo();
end $$;

